  $('#login-grant-form').addEventListener('submit',ev=>saveForm(ev,async d=>{await api('/admin/login-grants','POST',{account_id:id,agent_id:d.get('agent_id'),seconds:Number(d.get('seconds')),uses:d.get('use_mode')==='unlimited'?0:Number(d.get('uses')),unlimited_uses:d.get('use_mode')==='unlimited',read_path:d.get('read_path')});},t('登录授权已创建。Agent 现在可使用此授权引用。','Login grant created. The selected agent can now use its reference.')));
